<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cambiarEstadoPersonaProfesion, guardarPersonaProfesion, listarOpcionesPersonaProfesiones, listarPersonaProfesiones } from '../services/personaProfesiones'
import type { PersonaProfesion, PersonaProfesionCatalogo, PersonaProfesionPayload, PersonaProfesionPersona } from '../interfaces/personaProfesiones.interface'
const rows=ref<PersonaProfesion[]>([]),personas=ref<PersonaProfesionPersona[]>([]),profesiones=ref<PersonaProfesionCatalogo[]>([]),criterio=ref(''),personaFiltro=ref<number|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),form=reactive<PersonaProfesionPayload>({persona_id:0,profesion_id:0});const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function options(){try{const r=await listarOpcionesPersonaProfesiones();personas.value=r.personas;profesiones.value=r.profesiones}catch(v){error.value=message(v)}}
async function load(reset=false){if(reset)page.value=1;loading.value=true;error.value='';try{const r=await listarPersonaProfesiones(criterio.value,page.value,personaFiltro.value);rows.value=r.data;total.value=r.total;page.value=r.current_page;lastPage.value=r.last_page}catch(v){error.value=message(v)}finally{loading.value=false}}
function openCreate(){editing.value=null;form.persona_id=personaFiltro.value??0;form.profesion_id=0;error.value='';modal.value=true}
function openEdit(x:PersonaProfesion){editing.value=x.id;form.persona_id=x.persona_id;form.profesion_id=x.profesion_id;error.value='';modal.value=true}
async function save(){if(!form.persona_id||!form.profesion_id)return void(error.value='Debe seleccionar la persona y la profesión.');const duplicate=rows.value.some(x=>x.id!==editing.value&&x.persona_id===form.persona_id&&x.profesion_id===form.profesion_id);if(duplicate)return void(error.value='La profesión ya se encuentra registrada para el trabajador.');saving.value=true;error.value='';try{await guardarPersonaProfesion(editing.value,{...form});modal.value=false;success.value=`Profesión ${editing.value?'actualizada':'registrada'} correctamente.`;await load()}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(x:PersonaProfesion){const action=x.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} esta profesión del trabajador?`))return;try{const r=await cambiarEstadoPersonaProfesion(x.id);x.estado=r.estado;success.value=r.message??`Profesión ${r.estado?'activada':'desactivada'} correctamente.`}catch(v){error.value=message(v)}}
function move(v:number){if(v<1||v>lastPage.value)return;page.value=v;load()}onMounted(()=>Promise.all([options(),load()]))
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Profesiones por trabajador</nav><header class="hero"><div class="mark">PT</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Profesiones por trabajador</h1><p>Asignación y mantenimiento de la formación profesional del personal.</p></div><strong>{{total}} asignaciones</strong></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><label>Trabajador<select v-model="personaFiltro" @change="load(true)"><option :value="null">Todos los trabajadores</option><option v-for="x in personas" :key="x.id" :value="x.id">{{x.nombre_completo}} · {{x.dni||'Sin DNI'}}</option></select></label><form @submit.prevent="load(true)"><label>Buscar<input v-model.trim="criterio" placeholder="Profesión, código o trabajador"></label><button>Buscar</button><button v-if="criterio" type="button" class="soft" @click="criterio='';load(true)">Limpiar</button></form><button class="new" @click="openCreate">Asignar profesión</button></section><section class="table-card"><header><small>FORMACIÓN PROFESIONAL</small><h2>Profesiones registradas</h2></header><div v-if="loading" class="empty">Consultando profesiones…</div><div v-else-if="!rows.length" class="empty">No se encontraron profesiones asignadas.</div><div v-else class="scroll"><table><thead><tr><th>Trabajador</th><th>DNI</th><th>Código</th><th>Profesión</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="x in rows" :key="x.id"><td><b>{{x.persona?.nombre_completo??`Persona #${x.persona_id}`}}</b></td><td>{{x.persona?.dni||'—'}}</td><td><b>{{x.profesion?.codigo||'—'}}</b></td><td>{{x.profesion?.descripcion||'—'}}</td><td><span :class="x.estado?'active':'inactive'">{{x.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="openEdit(x)">Editar</button><button :class="x.estado?'disable':'enable'" @click="toggle(x)">{{x.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="move(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page>=lastPage" @click="move(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">PT</div><div><small>{{editing?'ACTUALIZAR ASIGNACIÓN':'NUEVA ASIGNACIÓN'}}</small><h2>{{editing?'Editar':'Asignar'}} profesión</h2></div><button type="button" class="close" @click="modal=false">×</button></header><label>Trabajador *<select v-model="form.persona_id" :disabled="editing!==null"><option :value="0">Seleccione una persona</option><option v-for="x in personas" :key="x.id" :value="x.id">{{x.nombre_completo}} · DNI {{x.dni||'—'}}</option></select></label><label>Profesión *<select v-model="form.profesion_id"><option :value="0">Seleccione una profesión</option><option v-for="x in profesiones" :key="x.id" :value="x.id">{{x.codigo}} · {{x.descripcion}}</option></select></label><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></div></div></template>
<style scoped>
