ve{display:inline-block;padding:4px 7px;border-radius:10px}.active{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.45rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;align-items:center;justify-content:center;gap:10px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:18px;display:grid;place-items:center;background:#172b3daa}.dialog{width:min(650px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:10px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.close{margin-left:auto;border:0;color:#59666c;background:none;font-size:1.3rem}.dialog label{display:block;margin-top:10px}.dialog>footer{margin-top:18px;display:flex;justify-content:flex-end;gap:7px}@media(max-width:900px){.hero,.filters,.filters form{flex-wrap:wrap}.hero>strong{margin-left:0}.filters>label,.filters form,.filters form label{width:100%}}
